// 1. Get the current item
const item = $input.item.json;

// 2. Extract and Clean Data
const title = item.title || "Unknown Gym";
const website = (item.website || "").toLowerCase().trim();
const phone = item.phoneUnformatted || item.phone || "";
const rating = parseFloat(item.totalScore || 0);
const reviews = parseInt(item.reviewsCount || 0);

// 3. Create the formatted Rating string: e.g., "4.8 (300)"
const ratingFormatted = `${rating} (${reviews})`;

// 4. Define the "Skip List" (Already has a real website)
const bigChains = ['anytimefitness', 'goldsgym', 'cult.fit', 'gethingyms'];
const isBigChain = bigChains.some(chain => title.toLowerCase().includes(chain) || website.includes(chain));

// 5. Define "Potential Lead" Social Platforms
const socialAsWebsite = [
    'instagram.com', 'facebook.com', 'youtube.com', 'youtu.be', 
    'twitter.com', 'x.com', 'threads.net', 'linkedin.com'
];

// 6. Logic: Filter and Identify Lead Type
let leadType = "";
let isHotLead = false;

if (!isBigChain) {
    if (website === "" || website.includes("google.com/search")) {
        leadType = "High Intent (No Website)";
        isHotLead = true;
    } 
    else if (socialAsWebsite.some(platform => website.includes(platform))) {
        const platformName = socialAsWebsite.find(p => website.includes(p)).split('.')[0];
        leadType = `Potential Client (Uses ${platformName} only)`;
        isHotLead = true;
    }
}

// 7. Output Result
if (isHotLead && phone !== "") {
    return {
        gym_name: title,
        phone: phone,
        email: item.email || "N/A",
        website_status: leadType,
        current_link: item.website || "None",
        area: item.neighborhood || item.city || "Kolkata",
        rating: ratingFormatted, // Now formatted as "4.8 (300)"
        maps_url: item.url,
        status: "New"
    };
}

return null;

const allItems = $input.all();
const existingPhones = new Map(); 
const existingNames = new Map();
const existingUrls = new Set();
const finalLeads = [];

// 1. Map out existing data from Sheet
allItems.forEach(item => {
    if (item.json.row_number) {
        const p = String(item.json.Phone || "").replace(/\D/g, "");
        const n = String(item.json["Gym Name"] || "").toLowerCase().trim();
        const u = item.json["Maps Link"] || "";
        const r = parseInt(item.json.Rating || 0);

        if (p) existingPhones.set(p, { name: n, reviews: r });
        if (n) existingNames.set(n, p);
        if (u) existingUrls.add(u);
    }
});

// 2. The Smart Logic Pass
allItems.forEach(item => {
    if (!item.json.row_number && item.json.gym_name) {
        const newP = String(item.json.phone || "").replace(/\D/g, "");
        const newN = item.json.gym_name.toLowerCase().trim();
        const newU = item.json.maps_url || "";
        const newR = parseInt(item.json.reviews || 0);

        let shouldAdd = true;
        let note = "";

        // Assumption 1: Exact Maps URL Match
        if (existingUrls.has(newU)) {
            shouldAdd = false; // Already in the sheet
        }

        // Assumption 2: Phone Match + Business Status check
        if (shouldAdd && existingPhones.has(newP)) {
            const oldData = existingPhones.get(newP);
            if (oldData.name !== newN) {
                note = `⚠️ Rebrand? Same number used by "${oldData.name}".`;
            } else if (newR > oldData.reviews + 20) {
                note = `🔥 Growth! They gained ${newR - oldData.reviews} new reviews.`;
            } else {
                shouldAdd = false; // Pure Duplicate
            }
        }

        // Assumption 3: Name Match + Different Number
        if (shouldAdd && existingNames.has(newN)) {
            const oldPhone = existingNames.get(newN);
            note = `📱 New Contact? Same name, but old number was ${oldPhone}.`;
        }

        if (shouldAdd) {
            finalLeads.push({
                json: {
                    gym_name: item.json.gym_name,
                    phone: item.json.phone,
                    email: item.json.email || "N/A",
                    website_status: item.json.website_status,
                    current_link: item.json.current_link || "None",
                    area: item.json.area,
                    rating: item.json.rating,
                    maps_url: item.json.maps_url,
                    status: "New",
                    date_added: new Date().toLocaleDateString('en-GB'),
                    notes: note
                }
            });
        }
    }
});

return finalLeads;
